class.description:
[HTTPResponse] holds the result of one request sent by an [HTTPRequest] node: the [member result] of the transfer, the HTTP [member status_code], the response [member headers] and the [member body]. It is passed to [signal HTTPRequest.response_received] after every completed request, including requests started with [method HTTPRequest.request] and [method HTTPRequest.request_raw]. All properties are read-only.
[codeblocks]
[gdscript]
func _on_response_received(response: HTTPResponse):
	if response.is_success():
		var data = response.get_json()
		print(data)
	else:
		print("Request failed: ", response.result, " ", response.status_code)
[/gdscript]
[csharp]
private void OnResponseReceived(HttpResponse response)
{
	if (response.IsSuccess())
	{
		Variant data = response.GetJson();
		GD.Print(data);
	}
	else
	{
		GD.Print("Request failed: ", response.Result, " ", response.StatusCode);
	}
}
[/csharp]
[/codeblocks]
